############### scripts/sfcc/_shared.mjs ###############
     1	/**
     2	 * Shared utilities for SFCC regional-config sync scripts.
     3	 * Provides SLAS token acquisition, Shopper Configurations (SCAPI) fetch
     4	 * helpers, and the same Tier-1-approver gh-identity check used by
     5	 * scripts/contentful/setup/getConfig.mjs.
     6	 */
     7	
     8	import { execSync } from 'child_process';
     9	
    10	/** Bounded timeout for both SCAPI requests below — a stalled connection to
    11	 * either endpoint must not hang `npm run sync:regional-config` indefinitely. */
    12	const REQUEST_TIMEOUT_MS = 20_000;
    13	
    14	export const log = {
    15	  info: (msg) => console.log(`  ℹ️  ${msg}`),
    16	  success: (msg) => console.log(`  ✅  ${msg}`),
    17	  skip: (msg) => console.log(`  ⏭️   ${msg}`),
    18	  warn: (msg) => console.warn(`  ⚠️  ${msg}`),
    19	  error: (msg) => console.error(`  ❌  ${msg}`),
    20	  section: (msg) => console.log(`\n── ${msg} ──`),
    21	};
    22	
    23	/**
    24	 * Validates that the required environment variables are set and non-empty.
    25	 * Exits the process with a descriptive message if any are missing.
    26	 * @param {string[]} required
    27	 */
    28	export function checkEnv(required) {
    29	  const missing = required.filter((k) => !process.env[k]);
    30	  if (missing.length) {
    31	    log.error(`Missing env vars: ${missing.join(', ')}`);
    32	    console.error('   Add them to .env (at repo root) and re-run.\n');
    33	    process.exit(1);
    34	  }
    35	}
    36	
    37	/**
    38	 * Checks whether the authenticated gh identity is a member of
    39	 * @ZimmermannAU/tier-1-approvers. Same pattern as
    40	 * scripts/contentful/setup/getConfig.mjs — a fast-fail convenience only;
    41	 * the real enforcement is GitHub branch protection + CODEOWNERS.
    42	 * @returns {Promise<{approved: boolean, login: string}>}
    43	 */
    44	export async function isTier1Approver() {
    45	  try {
    46	    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
    47	    const membersRaw = execSync("gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'", {
    48	      encoding: 'utf8',
    49	    }).trim();
    50	    const members = membersRaw.split('\n').filter(Boolean);
    51	    return { approved: members.includes(login), login };
    52	  } catch {
    53	    return { approved: false, login: 'unknown' };
    54	  }
    55	}
    56	
    57	/**
    58	 * Fetches a SLAS guest shopper access token using the private-client
    59	 * client_credentials grant (server-to-server, no shopper login) — the same
    60	 * credentials (COMMERCE_API_CLIENT_ID + PWA_KIT_SLAS_CLIENT_SECRET) the
    61	 * running storefront already uses. Guest tokens are scoped to a single
    62	 * site via `channel_id` (SLAS's name for the SFCC site ID) — SLAS rejects
    63	 * a guest token request with no channel_id, so a fresh token is needed per
    64	 * site rather than one shared token.
    65	 * @param {string} siteId the SFCC site ID to scope the token to
    66	 * @returns {Promise<string>} access token
    67	 */
    68	export async function getSlasToken(siteId) {
    69	  const { COMMERCE_API_SHORT_CODE, COMMERCE_API_ORGANIZATION_ID, COMMERCE_API_CLIENT_ID, PWA_KIT_SLAS_CLIENT_SECRET } =
    70	    process.env;
    71	  const url = `https://${COMMERCE_API_SHORT_CODE}.api.commercecloud.salesforce.com/shopper/auth/v1/organizations/${COMMERCE_API_ORGANIZATION_ID}/oauth2/token`;
    72	  const basicAuth = Buffer.from(`${COMMERCE_API_CLIENT_ID}:${PWA_KIT_SLAS_CLIENT_SECRET}`).toString('base64');
    73	
    74	  const response = await fetch(url, {
    75	    method: 'POST',
    76	    headers: {
    77	      Authorization: `Basic ${basicAuth}`,
    78	      'Content-Type': 'application/x-www-form-urlencoded',
    79	    },
    80	    body: new URLSearchParams({ grant_type: 'client_credentials', channel_id: siteId }).toString(),
    81	    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    82	  });
    83	
    84	  if (!response.ok) {
    85	    throw new Error(`SLAS token request failed for site '${siteId}': ${response.status} ${await response.text()}`);
    86	  }
    87	  const { access_token: accessToken } = await response.json();
    88	  return accessToken;
    89	}
    90	
    91	/**
    92	 * Fetches live site configuration (name, status, currencies, locales) for a
    93	 * single SFCC site from the Shopper Configurations API — the current,
    94	 * non-deprecated SCAPI successor to OCAPI's Data API site-preferences read.
    95	 * One call per site; there is no org-wide "list all sites" call.
    96	 * @param {string} accessToken SLAS shopper access token
    97	 * @param {string} siteId real SFCC site ID
    98	 * @returns {Promise<object>} the raw configurations response
    99	 */
   100	export async function fetchSiteConfiguration(accessToken, siteId) {
   101	  const { COMMERCE_API_SHORT_CODE, COMMERCE_API_ORGANIZATION_ID } = process.env;
   102	  const url = `https://${COMMERCE_API_SHORT_CODE}.api.commercecloud.salesforce.com/configuration/shopper-configurations/v1/organizations/${COMMERCE_API_ORGANIZATION_ID}/configurations?siteId=${encodeURIComponent(
   103	    siteId,
   104	  )}`;
   105	
   106	  const response = await fetch(url, {
   107	    headers: { Authorization: `Bearer ${accessToken}` },
   108	    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
   109	  });
   110	
   111	  if (!response.ok) {
   112	    throw new Error(
   113	      `Shopper Configurations request failed for site '${siteId}': ${response.status} ${await response.text()}`,
   114	    );
   115	  }
   116	  return response.json();
   117	}

