############### scripts/sfcc/syncRegionalConfig.mjs ###############
     1	#!/usr/bin/env node
     2	/**
     3	 * Sync live SFCC site/locale/currency config into the *.generated.* files
     4	 * that back config/sites.js, overrides/app/config/countries.ts,
     5	 * overrides/app/config/contentfulMapping.ts, and e2e/fixtures/site.js.
     6	 *
     7	 * Reads config/sites.overlay.js (hand-maintained routing data: alias,
     8	 * sfccSiteId) to find the real SFCC site IDs to query, fetches each site's
     9	 * live configuration via the Shopper Configurations API (SCAPI — the
    10	 * current, non-deprecated successor to OCAPI's Data API site-preferences
    11	 * read), then derives four outputs from that single fetch:
    12	 *
    13	 *   config/sites.generated.js                     — per real SFCC site
    14	 *   overrides/app/config/countries.generated.ts    — per URL slug
    15	 *   overrides/app/config/contentfulMapping.generated.ts — per PWA site id
    16	 *   e2e/fixtures/site.generated.js                 — per e2e fixture key
    17	 *
    18	 * Each consuming file (config/sites.js, countries.ts, contentfulMapping.ts,
    19	 * e2e/fixtures/site.js) merges its .generated file with a small
    20	 * hand-maintained overlay carrying the fields Business Manager/SCAPI has no
    21	 * concept of (URL aliases, checkout ownership, shipping country, boutique
    22	 * region, fixture-key naming) — see each file for its own merge logic.
    23	 *
    24	 * Write access to all four generated files is gated to
    25	 * @ZimmermannAU/tier-1-approvers, same pattern as
    26	 * scripts/contentful/setup/getConfig.mjs. Non-approvers get a read-only
    27	 * dry-run. (Only config/sites.generated.js sits under a directory
    28	 * frozenFiles.md explicitly marks Tier 1 — the other three are gated the
    29	 * same way anyway, since they carry the same class of routing-critical
    30	 * data.)
    31	 *
    32	 * Usage:
    33	 *   npm run sync:regional-config
    34	 *   npm run sync:regional-config -- --dry-run
    35	 */
    36	
    37	import { execSync } from 'child_process';
    38	import { existsSync, renameSync, unlinkSync, writeFileSync } from 'fs';
    39	import { createRequire } from 'module';
    40	import { dirname, resolve } from 'path';
    41	import { fileURLToPath } from 'url';
    42	import { checkEnv, fetchSiteConfiguration, getSlasToken, isTier1Approver, log } from './_shared.mjs';
    43	
    44	const require = createRequire(import.meta.url);
    45	const __dirname = dirname(fileURLToPath(import.meta.url));
    46	const REPO_ROOT = resolve(__dirname, '../../');
    47	const DRY_RUN = process.argv.includes('--dry-run');
    48	
    49	const SITES_OVERLAY_FILE = resolve(REPO_ROOT, 'config/sites.overlay.js');
    50	const E2E_OVERLAY_FILE = resolve(REPO_ROOT, 'e2e/fixtures/site.overlay.js');
    51	
    52	// AU is the app's defaultSite (config/default.js) and, by PWA Kit
    53	// convention, the one site with no URL alias — every other site's slug
    54	// comes directly from its locale's `alias` in sites.overlay.js.
    55	const ROOT_SITE_ID = 'ZimmermannAU';
    56	const ROOT_SLUG = 'au';
    57	
    58	const TARGETS = {
    59	  sites: {
    60	    file: resolve(REPO_ROOT, 'config/sites.generated.js'),
    61	    format: 'cjs',
    62	    consumer: 'config/sites.js',
    63	  },
    64	  countries: {
    65	    file: resolve(REPO_ROOT, 'overrides/app/config/countries.generated.ts'),
    66	    format: 'ts',
    67	    exportName: 'GENERATED_COUNTRIES',
    68	    consumer: 'overrides/app/config/countries.ts',
    69	  },
    70	  contentful: {
    71	    file: resolve(REPO_ROOT, 'overrides/app/config/contentfulMapping.generated.ts'),
    72	    format: 'ts-contentful',
    73	    consumer: 'overrides/app/config/contentfulMapping.ts',
    74	  },
    75	  e2eSite: {
    76	    file: resolve(REPO_ROOT, 'e2e/fixtures/site.generated.js'),
    77	    format: 'cjs',
    78	    consumer: 'e2e/fixtures/site.js',
    79	  },
    80	};
    81	
    82	checkEnv([
    83	  'COMMERCE_API_SHORT_CODE',
    84	  'COMMERCE_API_ORGANIZATION_ID',
    85	  'COMMERCE_API_CLIENT_ID',
    86	  'PWA_KIT_SLAS_CLIENT_SECRET',
    87	]);
    88	
    89	/**
    90	 * Extracts the fields these targets need from a Shopper Configurations
    91	 * response. The real response shape (confirmed against a live dev-realm
    92	 * call, not documented in the SDK's `any`-typed value field) is a FLAT
    93	 * array of `{configurationType, id, value}` entries — one per field, not a
    94	 * single nested object — mixing `siteConfiguration` entries (id/name/status/
    95	 * timezone/defaultCurrency/allowedCurrencies/defaultLocale/allowedLocales)
    96	 * with unrelated `globalConfiguration` entries (SalesforcePaymentsAllowed,
    97	 * my_domain). `allowedLocales` entries are rich objects
    98	 * ({id, country, displayName, ...}) with NO per-locale currency field, and
    99	 * always include a placeholder `{id: 'default', ...}` entry that isn't a
   100	 * real locale. Since every site here uses a single currency across all its
   101	 * locales (confirmed against the existing config/sites.js data), each real
   102	 * locale is assigned the site's own `defaultCurrency` as its
   103	 * `preferredCurrency` rather than reading a (non-existent) per-locale value.
   104	 */
   105	function extractSiteConfig(siteId, rawResponse) {
   106	  const fields = Object.fromEntries(
   107	    (rawResponse?.configurations ?? [])
   108	      .filter((c) => c.configurationType === 'siteConfiguration')
   109	      .map((c) => [c.id, c.value]),
   110	  );
   111	
   112	  // Fatal, not a warning: a malformed response for one site must abort the
   113	  // whole sync rather than silently drop that region from all four
   114	  // generated files while the run reports success for the rest.
   115	  const missingFields = ['defaultLocale', 'defaultCurrency', 'allowedCurrencies', 'allowedLocales'].filter(
   116	    (f) => !fields[f] || (Array.isArray(fields[f]) === false && (f === 'allowedCurrencies' || f === 'allowedLocales')),
   117	  );
   118	  if (missingFields.length) {
   119	    log.error(
   120	      `Incomplete Shopper Configurations response for '${siteId}' (missing ${missingFields.join(
   121	        ', ',
   122	      )}) — raw response below.`,
   123	    );
   124	    console.log(JSON.stringify(rawResponse, null, 2));
   125	    throw new Error(`Incomplete Shopper Configurations response for '${siteId}'.`);
   126	  }
   127	
   128	  const defaultCurrency = fields.defaultCurrency;
   129	  return {
   130	    status: fields.status,
   131	    defaultLocale: fields.defaultLocale,
   132	    defaultCurrency,
   133	    supportedCurrencies: fields.allowedCurrencies,
   134	    supportedLocales: fields.allowedLocales
   135	      .filter((l) => l.id !== 'default')
   136	      .map((l) => ({ id: l.id, preferredCurrency: defaultCurrency })),
   137	  };
   138	}
   139	
   140	/** ISO 4217 code -> display symbol (e.g. 'AUD' -> 'A$'), matching the
   141	 * disambiguated form Zimmermann's e2e fixtures already used by hand. */
   142	function currencySymbolFor(currencyCode) {
   143	  return new Intl.NumberFormat('en', { style: 'currency', currency: currencyCode })
   144	    .formatToParts(1)
   145	    .find((p) => p.type === 'currency').value;
   146	}
   147	
   148	/**
   149	 * Derives config/sites.generated.js's shape: real SFCC site id -> live
   150	 * config. Deliberately does NOT catch per-site failures — a transient SCAPI
   151	 * error or a malformed response for one site must abort the entire sync
   152	 * (nothing gets written, see main()) rather than silently ship a config
   153	 * that's missing that region across all four generated files.
   154	 */
   155	async function fetchGeneratedSites(overlay) {
   156	  const realSiteIds = [...new Set(overlay.map((s) => s.sfccSiteId ?? s.id))];
   157	  log.info(`Real SFCC sites to sync (deduped from ${overlay.length} PWA sites): ${realSiteIds.join(', ')}`);
   158	
   159	  const generated = {};
   160	  for (const siteId of realSiteIds) {
   161	    const accessToken = await getSlasToken(siteId);
   162	    const raw = await fetchSiteConfiguration(accessToken, siteId);
   163	    generated[siteId] = extractSiteConfig(siteId, raw);
   164	    const localeList = generated[siteId].supportedLocales.map((l) => l.id).join(',');
   165	    const currencyList = generated[siteId].supportedCurrencies?.join(',');
   166	    log.success(`${siteId}: ${localeList} / ${currencyList}`);
   167	  }
   168	  return generated;
   169	}
   170	
   171	/** Derives countries.generated.ts's shape: URL slug -> {sfccSiteId, locale, currency}. */
   172	function deriveCountriesGenerated(overlay, generated) {
   173	  const countriesGenerated = {};
   174	  for (const pwaSite of overlay) {
   175	    const sourceId = pwaSite.sfccSiteId ?? pwaSite.id;
   176	    const source = generated[sourceId];
   177	    if (!source) continue;
   178	    for (const loc of pwaSite.locales) {
   179	      const match = source.supportedLocales.find((l) => l.id === loc.id);
   180	      if (!match) continue;
   181	      const slug = loc.alias ?? (pwaSite.id === ROOT_SITE_ID ? ROOT_SLUG : loc.id);
   182	      countriesGenerated[slug] = { sfccSiteId: sourceId, locale: loc.id, currency: match.preferredCurrency };
   183	    }
   184	  }
   185	  return countriesGenerated;
   186	}
   187	
   188	/** Derives contentfulMapping.generated.ts's shape: SUPPORTED_LOCALES + SITE_LOCALES (per PWA site id). */
   189	function deriveContentfulGenerated(overlay, generated) {
   190	  const siteLocales = {};
   191	  const allLocaleIds = new Set();
   192	  for (const pwaSite of overlay) {
   193	    const sourceId = pwaSite.sfccSiteId ?? pwaSite.id;
   194	    const source = generated[sourceId];
   195	    if (!source) continue;
   196	    const localeIds = pwaSite.locales
   197	      .map((loc) => loc.id)
   198	      .filter((id) => source.supportedLocales.some((l) => l.id === id));
   199	    siteLocales[pwaSite.id] = localeIds;
   200	    localeIds.forEach((id) => allLocaleIds.add(id));
   201	  }
   202	  return { supportedLocales: [...allLocaleIds], siteLocales };
   203	}
   204	
   205	/** Derives e2e/fixtures/site.generated.js's shape: fixture key -> {locale, currency, currencySymbol, siteId}. */
